describe('Conflict Error Message on Stale Record Save', () => {
  beforeEach(() => {
    cy.visit('/records/new');
  });

  it('should display conflict error message when saving a stale record', () => {
    // Intercept the API call to get a stale record
    cy.intercept('POST', '/api/records/save', {
      statusCode: 200,
      body: {
        id: 123,
        data: {
          name: 'John Doe',
          email: 'john@example.com',
          status: 'active'
        },
        message: 'Record saved successfully'
      }
    }).as('saveRecord');

    // Fill in the form with stale data
    cy.get('[data-testid="record-name-input"]').type('John Doe');
    cy.get('[data-testid="record-email-input"]').type('john@example.com');
    cy.get('[data-testid="record-status-select"]').select('active');

    // Attempt to save the stale record
    cy.get('[data-testid="save-button"]').click();

    // Verify conflict error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Conflict');
    cy.get('[data-testid="error-message"]').should('contain', 'Record has been modified by another user');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify form is still visible
    cy.get('[data-testid="record-form"]').should('be.visible');
  });

  it('should handle conflict error gracefully and allow retry', () => {
    // Intercept the API call to get a stale record
    cy.intercept('POST', '/api/records/save', {
      statusCode: 409,
      body: {
        error: 'Conflict',
        message: 'Record has been modified by another user'
      }
    }).as('saveRecordConflict');

    // Fill in the form with stale data
    cy.get('[data-testid="record-name-input"]').type('Jane Smith');
    cy.get('[data-testid="record-email-input"]').type('jane@example.com');
    cy.get('[data-testid="record-status-select"]').select('active');

    // Attempt to save the stale record
    cy.get('[data-testid="save-button"]').click();

    // Verify conflict error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Conflict');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Verify error message disappears
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify form is still visible
    cy.get('[data-testid="record-form"]').should('be.visible');

    // Verify save button is now enabled
    cy.get('[data-testid="save-button"]').should('be.enabled');
  });
});
